async function api<T>(path: string, options: RequestInit = {}): Promise<T> {
  const method = (options.method ?? "GET").toUpperCase();
  const csrfToken = document.cookie.split("; ").find((item) => item.startsWith("commandos_csrf="))?.split("=")[1];
  const response = await fetch(path, { ...options, credentials: "include", headers: { "Content-Type": "application/json", ...(method !== "GET" && csrfToken ? { "X-CSRF-Token": decodeURIComponent(csrfToken) } : {}), ...options.headers } });
  if (!response.ok) {
    const body = await response.json().catch(() => ({ detail: "Request failed" }));
    throw new Error(body.detail ?? "Request failed");
  }
  if (response.status === 204) return undefined as T;
  return response.json() as Promise<T>;
}

