function EmptyState({ title, text, action }: { title: string; text: string; action?: ReactNode }) { return <div className="empty-state"><div className="empty-orbit"><span /></div><h3>{title}</h3><p>{text}</p>{action}</div>; }

function Login() {
  const queryClient = useQueryClient(); const [email, setEmail] = useState(""); const [password, setPassword] = useState("");
  const login = useMutation({ mutationFn: () => api<void>("/api/auth/login", { method: "POST", body: JSON.stringify({ email, password }) }), onSuccess: () => queryClient.invalidateQueries({ queryKey: ["me"] }) });
  const submit = (event: FormEvent) => { event.preventDefault(); login.mutate(); };
  return <main className="auth-shell"><section className="auth-card"><div className="wordmark"><span className="wordmark-glyph">C</span><span><b>Command</b>OS</span></div><div className="auth-copy"><p className="eyebrow">Private creator intelligence</p><h1>Turn content data into your next best move.</h1><p>One operating system for CloudDataFriend analytics, research, strategy and production.</p></div><form onSubmit={submit}><label>Email<input type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@example.com" required /></label><label>Password<input type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="••••••••" required /></label>{login.error && <p className="error" role="alert">{login.error.message}</p>}<button className="button primary wide" disabled={login.isPending}>{login.isPending ? "Signing in…" : "Enter CommandOS"}<Icon name="arrow" /></button></form><p className="auth-note">Single-owner workspace · Read-only social access</p></section><aside className="auth-visual"><div className="auth-loop"><span>Collect</span><i/><span>Research</span><i/><span>Decide</span><i/><span>Create</span><i/><span>Learn</span></div><div className="auth-quote">“Content intuition gets stronger when the evidence is in the room.”</div></aside></main>;
}

